package cpw.mods.fml.common.gameevent;
public final class PlayerEvent { public static final class ItemCraftedEvent { public final net.minecraft.entity.player.EntityPlayer player;public final net.minecraft.item.ItemStack crafting;public ItemCraftedEvent(net.minecraft.entity.player.EntityPlayer p,net.minecraft.item.ItemStack s){player=p;crafting=s;} }public static final class ItemSmeltedEvent { public final net.minecraft.entity.player.EntityPlayer player;public final net.minecraft.item.ItemStack smelting;public ItemSmeltedEvent(net.minecraft.entity.player.EntityPlayer p,net.minecraft.item.ItemStack s){player=p;smelting=s;} }public static final class ItemPickupEvent { public final net.minecraft.entity.player.EntityPlayer player;public final net.minecraft.entity.item.EntityItem pickedUp;public ItemPickupEvent(net.minecraft.entity.player.EntityPlayer p,net.minecraft.entity.item.EntityItem s){player=p;pickedUp=s;} } }
